#include <iostream>
#include <stdio.h>
#define N 1000
const int X = 2;
const int Y = 2;
int cache[1000];
int game(int);
int main() {
	int n;
	scanf("%d",&n);
	for(int i=0;i<=n;i++) {
		cache[i] = -1;
	}
	cache[0] = 1;
	if(game(n) == 1) {
		printf("A\n");
	}else {
		printf("B\n");
	}
	return 0;
}

int game(int n_c) {
	if(cache[n_c] != -1) {
		return cache[n_c];
	}
	int p = 1,q = 1,r = 1;
	if(n_c >=1) p = game(n_c-1);
	if(n_c >=X) q = game(n_c-X); 
	if(n_c >=Y) r = game(n_c-Y);

	if( !(p && q && r)) {
		return 1;
	}else {
		return 0;
	}
}
